def zigzagLevelSum(root):
    # (TreeNode is provided by LeetCode: .val, .left, .right)
    ans = []
    level_nodes = [root]          # all nodes of the current level, left to right
    level = 1                     # 1-indexed level number
    while level_nodes:
        total = 0
        if level % 2 == 1:
            # odd level: left to right, stop at the first node without a left child
            for node in level_nodes:
                if node.left is None:
                    break
                total += node.val
        else:
            # even level: right to left, stop at the first node without a right child
            for idx in range(len(level_nodes) - 1, -1, -1):
                node = level_nodes[idx]
                if node.right is None:
                    break
                total += node.val
        ans.append(total)
        # The next level contains the children of EVERY node, not only the processed ones
        next_nodes = []
        for node in level_nodes:
            if node.left:
                next_nodes.append(node.left)
            if node.right:
                next_nodes.append(node.right)
        level_nodes = next_nodes
        level += 1
    return ans
